"""Safe text extraction from uploaded PDF / DOCX files."""
import io
import re
import zipfile

from docx import Document
from pypdf import PdfReader

from .config import MAX_DOCX_UNCOMPRESSED_BYTES, MAX_TEXT_CHARS, MAX_UPLOAD_BYTES


class UploadError(ValueError):
    """Raised when an uploaded file is rejected. `code` is an i18n key for the UI."""

    def __init__(self, code: str):
        super().__init__(code)
        self.code = code


def _clean(text: str) -> str:
    """Normalise whitespace while keeping line structure."""
    text = text.replace("\r\n", "\n").replace("\r", "\n").replace("\u00a0", " ")
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return "\n".join(line.strip() for line in text.split("\n")).strip()


def _extract_pdf(data: bytes) -> tuple[str, dict]:
    """Extract text from a PDF and collect ATS-relevant metadata."""
    reader = PdfReader(io.BytesIO(data))
    if reader.is_encrypted:
        raise UploadError("err_encrypted")
    pages = [page.extract_text() or "" for page in reader.pages[:10]]
    text = "\n".join(pages)
    images = 0
    for page in reader.pages[:10]:
        try:
            images += len(page.images)
        except Exception:  # malformed image streams should not block parsing
            pass
    return text, {"format": "pdf", "pages": len(reader.pages), "images": images, "tables": 0,
                  "header_footer_text": False}


def _extract_docx(data: bytes) -> tuple[str, dict]:
    """Extract text from a DOCX (paragraphs + tables) after zip-bomb checks."""
    try:
        with zipfile.ZipFile(io.BytesIO(data)) as zf:
            if "word/document.xml" not in zf.namelist():
                raise UploadError("err_invalid_file")
            if sum(i.file_size for i in zf.infolist()) > MAX_DOCX_UNCOMPRESSED_BYTES:
                raise UploadError("err_too_large")
    except zipfile.BadZipFile as exc:
        raise UploadError("err_invalid_file") from exc

    doc = Document(io.BytesIO(data))
    lines = [p.text for p in doc.paragraphs]
    for table in doc.tables:
        for row in table.rows:
            cells = []
            for cell in row.cells:
                if cell.text.strip() and cell.text not in cells:
                    cells.append(cell.text)
            lines.append(" | ".join(cells))
    header_footer = any(
        p.text.strip()
        for s in doc.sections
        for part in (s.header, s.footer)
        for p in part.paragraphs
    )
    return "\n".join(lines), {"format": "docx", "pages": None, "images": len(doc.inline_shapes),
                              "tables": len(doc.tables), "header_footer_text": header_footer}


def extract_text(filename: str, data: bytes) -> tuple[str, dict]:
    """Validate an upload by extension AND magic bytes, then extract text.

    Security: never trusts the client-supplied content type; enforces size limits
    and rejects encrypted/invalid documents.
    """
    if not data:
        raise UploadError("err_empty")
    if len(data) > MAX_UPLOAD_BYTES:
        raise UploadError("err_too_large")
    name = (filename or "").lower()
    try:
        if name.endswith(".pdf") and data[:5] == b"%PDF-":
            text, meta = _extract_pdf(data)
        elif name.endswith(".docx") and data[:4] == b"PK\x03\x04":
            text, meta = _extract_docx(data)
        elif name.endswith(".txt"):
            text, meta = data.decode("utf-8", errors="replace"), {"format": "txt", "pages": None,
                                                                    "images": 0, "tables": 0,
                                                                    "header_footer_text": False}
        else:
            raise UploadError("err_unsupported")
    except UploadError:
        raise
    except Exception as exc:  # corrupted documents
        raise UploadError("err_invalid_file") from exc

    text = _clean(text)[:MAX_TEXT_CHARS]
    if len(text) < 30:
        # Usually a scanned / image-only PDF that ATS cannot read either.
        raise UploadError("err_no_text")
    return text, meta
